[{"order":1,"type":"heading","text":"Hibernate Association Mappings: A Technical Guide"},{"order":2,"type":"paragraph","text":"Association mappings are the core of Object-Relational Mapping (ORM) frameworks like Hibernate. They allow developers to map domain object relationships directly to relational database foreign key constraints. This tutorial explores the four primary association types: One-to-One, One-to-Many, Many-to-One, and Many-to-Many."},{"order":3,"type":"subheading","text":"1. One-to-One Association"},{"order":4,"type":"paragraph","text":"A One-to-One association means that one record in a table is linked to exactly one record in another table. A common example is a User and their Profile."},{"order":5,"type":"code","text":"@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @OneToOne(mappedBy = "user", cascade = CascadeType.ALL)
    private UserProfile profile;
}"},{"order":6,"type":"subheading","text":"2. Many-to-One and One-to-Many Associations"},{"order":7,"type":"paragraph","text":"These are the most common associations. A Many-to-One relationship usually owns the foreign key (e.g., many Tasks belong to one Department). The One-to-Many side represents the inverse collection."},{"order":8,"type":"code","text":"@Entity
@Table(name = "tasks")
public class Task {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String title;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "department_id")
    private Department department;
}"},{"order":9,"type":"paragraph","text":"On the inverse Department side, the collection is mapped using the mappedBy attribute."},{"order":10,"type":"code","text":"@Entity
@Table(name = "departments")
public class Department {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    @OneToMany(mappedBy = "department", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Task> tasks = new ArrayList<>();
}"},{"order":11,"type":"subheading","text":"3. Many-to-Many Association"},{"order":12,"type":"paragraph","text":"A Many-to-Many association requires an intermediate join table to map records from both entities. Examples include Students and Courses."},{"order":13,"type":"code","text":"@Entity
@Table(name = "students")
public class Student {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToMany
    @JoinTable(
        name = "student_course",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}"},{"order":14,"type":"subheading","text":"Best Practices for Hibernate Associations"},{"order":15,"type":"bullet_point","text":"Always use FetchType.LAZY for collection mappings (OneToMany, ManyToMany) to prevent performance degradation."},{"order":16,"type":"bullet_point","text":"Implement hashCode() and equals() carefully when using bidirectional associations, relying on business keys or immutable database IDs."},{"order":17,"type":"bullet_point","text":"Use orphanRemoval = true to automatically delete child entities when they are removed from the parent collection."}]
